// PHASE 1 plan. Weekly target = Settings 'Weekly New Leads' (default 25). Countries = Settings 'Target Countries' (empty = Turkey).
// Plans about target / 4 briefs (min 6, max 18 per country) for the target countries. If they come up short,
// 'Fallback Plan' searches the other supported countries for the rest.
const SUPPORTED = ['Turkey', 'Bangladesh', 'Vietnam', 'Malaysia', 'Brazil'];
const PER_BRIEF = 4; // expected new companies per brief after dedupe (used to size the plan)

// Turkey: 3 briefs per segment (general, then two city focuses), so a big weekly target still finds fresh companies.
const turkeyBriefs = [
  { segment: 'Knitwear', brief: 'Turkish knitwear (örme) manufacturers exporting to EU brands', queries: ['Türkiye örme konfeksiyon ihracatçı firma Avrupa', 'Turkish knitwear manufacturer exporting to Europe EU brands', 'İHKİB örme hazır giyim ihracat ödülü firma listesi'] },
  { segment: 'Woven apparel', brief: 'Turkish woven apparel and shirt manufacturers producing for European retailers', queries: ['Türkiye dokuma gömlek üreticisi ihracat Avrupa', 'Turkish woven garment shirt manufacturer export Europe retailers', 'İHKİB dokuma konfeksiyon ihracat şampiyonları firma'] },
  { segment: 'Denim', brief: 'Turkish denim and jeans manufacturers supplying EU brands', queries: ['Türkiye denim jean üreticisi Avrupa ihracat', 'Turkish denim jeans manufacturer supplying European brands', 'Denim Première Vision Istanbul Turkish denim exhibitor'] },
  { segment: 'Home textile', brief: 'Turkish home textile exporters (towels, bedding) selling to the EU', queries: ['Denizli havlu bornoz ihracatçı firma Avrupa', 'Turkish home textile towel bedding manufacturer export Europe', 'Bursa ev tekstili ihracatçı üretici Avrupa'] },
  { segment: 'Fabric mill', brief: 'Turkish fabric mills with OEKO-TEX, GOTS or GRS certification exporting to Europe', queries: ['Türkiye kumaş üreticisi GOTS OEKO-TEX ihracat Avrupa', 'Turkish fabric mill GOTS GRS certified exporting to Europe', 'Texworld Paris Turkish fabric mill exhibitor'] },
  { segment: 'Sportswear', brief: 'Turkish sportswear and activewear manufacturers for EU brands', queries: ['Türkiye spor giyim activewear üreticisi ihracat Avrupa', 'Turkish sportswear activewear manufacturer for European brands', 'İzmir activewear manufacturer export EU'] },
  { segment: 'Knitwear', brief: 'Knitwear and knitted fabric manufacturers in Istanbul and Tekirdağ (Çorlu, Çerkezköy) exporting to Europe', queries: ['İstanbul triko örme giyim üreticisi ihracat Almanya', 'Çorlu Çerkezköy örme kumaş konfeksiyon fabrikası ihracat', 'Istanbul knitwear factory exporting to Germany Netherlands'] },
  { segment: 'Woven apparel', brief: 'Woven apparel manufacturers in İzmir and Denizli producing for European retailers', queries: ['İzmir konfeksiyon fabrikası ihracat Avrupa markaları', 'Denizli gömlek dokuma konfeksiyon ihracatçı', 'Izmir garment manufacturer export European retailers'] },
  { segment: 'Denim', brief: 'Denim fabric and jeans producers in Adana, Kahramanmaraş and Istanbul selling to EU brands', queries: ['Kahramanmaraş denim kumaş üreticisi ihracat Avrupa', 'Adana denim jean konfeksiyon ihracat', 'Istanbul jeans manufacturer private label Europe'] },
  { segment: 'Home textile', brief: 'Home textile manufacturers in Uşak, Denizli and Bursa (blankets, bathrobes, curtains) exporting to Europe', queries: ['Uşak battaniye ev tekstili ihracatçı Avrupa', 'Denizli bornoz nevresim üreticisi ihracat Almanya', 'Bursa perde döşemelik kumaş ihracatçı firma'] },
  { segment: 'Fabric mill', brief: 'Fabric and yarn mills in Gaziantep, Kahramanmaraş and Kayseri exporting to Europe', queries: ['Gaziantep iplik dokuma fabrikası ihracat Avrupa', 'Kahramanmaraş iplik kumaş üreticisi GRS sertifikalı', 'Kayseri dokuma kumaş fabrikası ihracat AB'] },
  { segment: 'Sportswear', brief: 'Sportswear, swimwear and underwear manufacturers in Istanbul and Bursa for EU brands', queries: ['İstanbul mayo iç giyim üreticisi ihracat Avrupa', 'Bursa spor giyim tekstil üreticisi ihracat', 'Turkish swimwear underwear manufacturer for European brands'] },
  { segment: 'Knitwear', brief: 'Turkish children and baby wear manufacturers exporting to EU retailers', queries: ['Türkiye bebek çocuk giyim üreticisi ihracat Avrupa', 'Turkish babywear manufacturer GOTS organic export Europe', 'Bursa çocuk giyim ihracatçı firma'] },
  { segment: 'Woven apparel', brief: 'Turkish outerwear, workwear and uniform manufacturers exporting to the EU', queries: ['Türkiye iş elbisesi üniforma üreticisi ihracat Avrupa', 'Turkish workwear manufacturer export Europe', 'Türkiye dış giyim mont kaban üreticisi ihracat'] },
  { segment: 'Other', brief: 'Turkish technical textile and nonwoven manufacturers exporting to Europe', queries: ['Türkiye teknik tekstil üreticisi ihracat Avrupa', 'Turkish technical textile nonwoven manufacturer export EU', 'Gaziantep nonwoven halı tabanı üreticisi ihracat'] },
  { segment: 'Home textile', brief: 'Turkish carpet and rug manufacturers in Gaziantep and Uşak exporting to Europe', queries: ['Gaziantep makine halısı üreticisi ihracat Avrupa', 'Turkish carpet rug manufacturer export Europe', 'Uşak halı kilim ihracatçı firma'] },
