const hints = {
  Bangladesh: { adj: 'Bangladeshi', hubs: ['Dhaka', 'Gazipur', 'Chattogram'], assoc: 'BGMEA BKMEA' },
  Vietnam: { adj: 'Vietnamese', hubs: ['Ho Chi Minh City', 'Binh Duong', 'Hanoi'], assoc: 'VITAS' },
  Malaysia: { adj: 'Malaysian', hubs: ['Penang', 'Johor', 'Selangor'], assoc: 'MTMA Malaysian Textile Manufacturers Association' },
  Brazil: { adj: 'Brazilian', hubs: ['Santa Catarina', 'São Paulo', 'Ceará'], assoc: 'ABIT', pt: true },
};
const segments = [
  { segment: 'Knitwear', what: 'knitwear', pt: 'malharia confecção exportadora Europa' },
  { segment: 'Woven apparel', what: 'woven garment and shirt', pt: 'confecção tecido plano camisas exportação Europa' },
  { segment: 'Denim', what: 'denim and jeans', pt: 'fabricante denim jeans exportação Europa' },
  { segment: 'Home textile', what: 'home textile (towels, bedding)', pt: 'cama mesa banho exportadora Europa' },
  { segment: 'Fabric mill', what: 'fabric mill (GOTS, OEKO-TEX or GRS certified)', pt: 'tecelagem GOTS OEKO-TEX exportação Europa' },
  { segment: 'Sportswear', what: 'sportswear and activewear', pt: 'fabricante moda fitness activewear exportação Europa' },
];
function briefsFor(country) {
  if (country === 'Turkey') return turkeyBriefs;
  const h = hints[country];
  return segments.map(s => ({
    segment: s.segment,
    brief: h.adj + ' ' + s.what + ' manufacturers exporting to EU brands and retailers',
    queries: [
      h.adj + ' ' + s.what + ' manufacturer exporter Europe EU brands',
      s.what + ' factory ' + h.hubs[0] + ' export to Europe',
      h.pt ? s.pt : h.assoc + ' member ' + s.what + ' exporter Europe ' + h.hubs.slice(1).join(' '),
    ],
  }));
}
function parseCountries(raw) {
  const list = [];
  for (const part of String(raw || '').split(/[,;\n]/)) {
    const key = part.trim().toLowerCase().replace('türkiye', 'turkey').replace('turkiye', 'turkey');
    const hit = SUPPORTED.find(c => c.toLowerCase() === key);
    if (hit && list.indexOf(hit) === -1) list.push(hit);
  }
  return list;
}
// Round-robin over countries so each gets a fair share of briefs.
function interleave(countries, n) {
  const pools = countries.map(c => briefsFor(c).map(b => ({ ...b, country: c })));
  const out = [];
  for (let k = 0; out.length < n && pools.some(p => k < p.length); k++) for (const p of pools) if (k < p.length && out.length < n) out.push(p[k]);
  return out;
}
function domainOf(url) { return String(url || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').split('/')[0].split(':')[0].trim(); }
function norm(name) { return String(name || '').toLowerCase().replace(/\b(a\.?ş\.?|a\.?s\.?|ltd\.?|şti\.?|sti\.?|san\.?|tic\.?|ve|tekstil|textile|textiles|konfeksiyon)\b/g, ' ').replace(/[^a-z0-9çğıöşü]+/g, ' ').trim(); }
function countryKey(raw) { return String(raw || '').trim().toLowerCase().replace('türkiye', 'turkey').replace('turkiye', 'turkey').replace('viet nam', 'vietnam').replace('brasil', 'brazil'); }

const settings = $('Read Settings').first().json || {};
const target = Math.max(1, Math.min(200, parseInt(settings['Weekly New Leads'], 10) || 25));
let countries = parseCountries(settings['Target Countries']);
if (!countries.length) countries = ['Turkey'];
const maxBriefs = countries.reduce((n, c) => n + briefsFor(c).length, 0);
const n = Math.min(maxBriefs, Math.max(6, Math.ceil(target / PER_BRIEF)));
const existing = $('Get Existing Leads').all().map(i => i.json).filter(r => r && (r['Company'] || r['Website']));
const excludeText = existing.map(r => String(r['Company'] || '').trim()).filter(Boolean).slice(-300).join('; ') || '(none)';
const runDate = new Date().toISOString().slice(0, 10);
return interleave(countries, n).map((b, k) => ({ json: {
  phase: 1, brief_no: k + 1, country: b.country, countries: countries.join(', '), target,
  segment: b.segment, brief: b.brief, queries_text: b.queries.map((q, j) => `${j + 1}. ${q}`).join('\n'),
  exclude: excludeText, run_date: runDate,
} }));

