function classify(seg) {
  const s = String(seg || '').toLowerCase();
  if (/integrated|entegre/.test(s)) return ['Entegre tesis', '1'];
  if (/home|towel|bedding|carpet|rug/.test(s)) return ['Ev tekstili', '2'];
  if (/workwear|uniform/.test(s)) return ['İş kıyafeti', '2'];
  if (/knitwear|woven apparel|sportswear|garment|apparel/.test(s)) return ['Hazır giyim / konfeksiyon', '1'];
  if (/fabric|yarn|mill|dye/.test(s)) return ['Kumaş / iplik / boyahane', '2'];
  return null;
}
