// One item per company found, in the shape Dedupe expects. Replies without JSON are skipped. Input can come from the main Claude node or the account-2 fallback, so the segment and country come from Claude's answer.
function strings(v, acc) {
  if (typeof v === 'string') acc.push(v);
  else if (Array.isArray(v)) v.forEach(x => strings(x, acc));
  else if (v && typeof v === 'object') Object.values(v).forEach(x => strings(x, acc));
  return acc;
}
function extract(text) {
  const s = text.indexOf('{'); const e = text.lastIndexOf('}');
  if (s < 0 || e <= s) return null;
  for (let end = e; end > s; end = text.lastIndexOf('}', end - 1)) {
    try { const o = JSON.parse(text.slice(s, end + 1)); if (o && Array.isArray(o.companies)) return o; } catch (err) { /* try a shorter slice */ }
  }
  return null;
}
const out = [];
$input.all().forEach((item) => {
  const body = item.json || {};
  const texts = strings(body, []).filter(t => t.includes('"companies"'));
  let parsed = null;
  for (const t of texts) { parsed = extract(t); if (parsed) break; }
  if (!parsed) return;
  for (const c of parsed.companies) {
    if (!c || typeof c !== 'object') continue;
    out.push({ json: {
      company: String(c.company || '').trim(),
      website: String(c.website || '').trim(),
      segment: String(c.segment || '').trim(),
      country: String(c.country || '').trim(),
      eu_evidence: String(c.eu_evidence || '').trim(),
      source_url: String(c.source_url || '').trim(),
      confidence: Number(c.confidence || 0),
    } });
  }
});
return out.filter(i => i.json.company && i.json.website);

// Telegram summary of this run (user 2026-11-16): how many new companies were added, by country, and what was skipped.
const esc = (t) => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const s = $('Read Settings').first().json || {};
const chatId = String(s['Nil Telegram Chat ID'] || '').trim();
if (!chatId) return [];
const added = $input.all().map(i => i.json || {});
const byCountry = {};
for (const r of added) byCountry[r.Country || '?'] = (byCountry[r.Country || '?'] || 0) + 1;
const p = $('Build Search Plan').first().json || {};
const skipped = String((added[0] || {}).skipped_summary || '').replace(/^.*?skipped /, '');
let sk = {};
try { sk = JSON.parse(skipped); } catch (e) {}
const lines = ['<b>Texprove: company search done</b>', 'Added ' + added.length + ' new companies (target ' + (p.target || '?') + '): ' + Object.entries(byCountry).map(([c, n]) => esc(c) + ' ' + n).join(', ')];
const parkedN = added.filter(r => r.Stage === 'Parked - Wave 2').length;
if (parkedN) lines.push(parkedN + ' of them are wave 2 (fabric, yarn, home textile, workwear): recorded only, no research and no draft.');
const parts = [];
if (sk.duplicate) parts.push(sk.duplicate + ' already in the sheet');
if (sk.lowConfidence) parts.push(sk.lowConfidence + ' low confidence');
if (sk.noSource) parts.push(sk.noSource + ' no source');
if (sk.otherCountry) parts.push(sk.otherCountry + ' wrong country');
if (sk.overTarget) parts.push(sk.overTarget + ' over the target');
if (parts.length) lines.push('Skipped: ' + parts.join(', ') + '.');
lines.push('Research starts with the next WF1 run (15 per weekday).');
return [{ json: { chatId, text: lines.join('\n').slice(0, 4000) } }];

// Wave 1 first (Nil's decisions of 23 Nov 2026, section 4): the weekly search goes mainly to EU-exporting garment
// makers and integrated groups. Briefs for wave-2 segments (home textile, fabric and yarn mills, technical textile)
// are swapped for the garment briefs below; at most two wave-2 briefs stay per run, so those firms are still recorded.
const WAVE2 = ['Home textile', 'Fabric mill', 'Other', 'Yarn', 'Technical textile'];
const KEEP_WAVE2 = 2;
const extra = [
  { segment: 'Integrated', brief: 'Turkish vertically integrated textile groups (yarn or fabric and garment production in one group) exporting garments to the EU', queries: ['Türkiye entegre tekstil grubu iplik kumaş konfeksiyon ihracat Avrupa', 'Turkish vertically integrated textile group garment export Europe', 'entegre tesis hazır giyim ihracatçı İSO 500 tekstil'] },
  { segment: 'Knitwear', brief: 'Turkish t-shirt, sweatshirt and jersey garment manufacturers in Istanbul, Izmir and Bursa exporting to EU brands', queries: ['İstanbul tişört sweatshirt üreticisi ihracat Avrupa markaları', 'Turkish t-shirt sweatshirt manufacturer GOTS export Europe', 'İzmir örme konfeksiyon ihracatçı firma Almanya'] },
  { segment: 'Woven apparel', brief: 'Turkish womenswear and dress manufacturers producing for European fashion retailers', queries: ['Türkiye kadın giyim elbise üreticisi ihracat Avrupa', 'Turkish womenswear dress manufacturer for European retailers', 'İstanbul hazır giyim ihracatçı kadın giyim fason üretim Avrupa'] },
  { segment: 'Sportswear', brief: 'Turkish underwear, lingerie and nightwear manufacturers exporting to the EU', queries: ['Türkiye iç giyim pijama üreticisi ihracat Avrupa', 'Turkish underwear lingerie nightwear manufacturer export Europe', 'İstanbul iç giyim ihracatçı firma Almanya Fransa'] },
  { segment: 'Denim', brief: 'Turkish jeans and denim garment manufacturers (cut, sew and wash) producing for European brands', queries: ['Türkiye jean konfeksiyon yıkama üreticisi ihracat Avrupa', 'Turkish jeans garment manufacturer laundry export European brands', 'Tekirdağ Çorlu denim konfeksiyon ihracatçı'] },
  { segment: 'Woven apparel', brief: 'Turkish menswear, suit and trouser manufacturers exporting to EU retailers', queries: ['Türkiye erkek giyim takım elbise pantolon üreticisi ihracat Avrupa', 'Turkish menswear suit trouser manufacturer export Europe', 'İzmir erkek giyim ihracatçı üretici Avrupa'] },
  { segment: 'Knitwear', brief: 'Turkish garment exporters on the İHKİB and TİM top exporter lists (ready-made garments)', queries: ['İHKİB hazır giyim ihracatın yıldızları firma listesi', 'TİM ilk 1000 ihracatçı hazır giyim konfeksiyon firma', 'EHKİB hazır giyim ihracat ödülleri firma'] },
];
// Added to every brief: traders, wholesalers and domestic-only firms are out of scope.
const ONLY = '. Only companies with their own production that export to the EU: no wholesalers, no traders without production, no companies that sell only in their home market';
let kept = 0;
let k = 0;
return $input.all().map((item) => {
  const j = item.json || {};
  if (j.country !== 'Turkey' || !WAVE2.includes(j.segment)) return { json: { ...j, brief: j.brief + ONLY } };
  if (kept < KEEP_WAVE2) { kept++; return { json: { ...j, brief: j.brief + ONLY } }; }
  if (k >= extra.length) return { json: { ...j, brief: j.brief + ONLY } };
  const b = extra[k++];
  return { json: { ...j, segment: b.segment, brief: b.brief + ONLY, queries_text: b.queries.map((q, n) => `${n + 1}. ${q}`).join('\n') } };
});
